def __init__(self, credential: Optional[str]=None, message: str=
    'Your authentication credential{credential}is invalid. See {link}.',
    reason: Optional[str]=None):
    self.credential = credential
    self.link = 'https://docs.safetycli.com/safety-docs/support/invalid-api-key-error'
    if self.credential:
        self.message = message.format(credential=f" '{self.credential}' ", link=self.link)
    else:
        self.message = message.format(credential=' ', link=self.link)
    if reason:
        self.message += f" Reason: {reason}"
    super().__init__(self.message)

